// Scores the level out of 100 and caches each pillar on the object.
// isAct marks the committed DOL: the near-distance taper only screens NEW targets.
// A target price is closing in on is being delivered; it must not lose its
// proximity (and its place) to a pool further out just before it is taken.
method evaluate(Level this, float px, float atrV, array<float> anchors, float confTol, float dirD, float sig, float mu, bool isAct) =>
    float dist  = math.max(0.0, this.distance(px))
    float dAtr  = dist / atrV
    float lin   = dAtr >= maxATR ? 0.0 : 1.0 - dAtr / maxATR
    float reach = dAtr >= maxATR ? 0.0 : sig > 0 ? f_pot(dist, sig, mu * this.side, potH) / 0.95 : lin
    float taper = minDistATR > 0 and not isAct ? math.min(1.0, dAtr / minDistATR) : 1.0

// a level survives on its score OR on its direction-neutral pillars: ranking by
// score alone (draw pillar, counter-draw x0.5, origin lockout x0.25) discards
// every fresh FVG / OB / breaker and the whole counter side once the pool is full
float neu = 100.0 * (wProx * lv.prox + wFresh * lv.fresh + wConf * lv.conf + wDens * lv.dens) / math.max(wSum - wDraw, 1e-9)
float key = math.max(lv.score, neu) + (lv.src >= 1 ? 10.0 : 0.0)

// out of range: beyond Max ATR Distance on the slow-ATR yardstick the registry
// re-enters with, proximity is 0 and PoT ~0%. Such a level can neither be chosen
// nor kept as the DOL (it stays in the pool for re-entry until ejected).
for lv in pool
    if lv.distance(close) / atrE > maxATR
        lv.score := 0.0

